<span class="line">            <span class="token keyword">return</span> <span class="token punctuation">(</span>value <span class="token operator">==</span> <span class="token string">&quot;1&quot;</span> <span class="token operator">||</span> value <span class="token operator">==</span> <span class="token string">&quot;true&quot;</span><span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token string">&quot;true&quot;</span> <span class="token operator">:</span> <span class="token string">&quot;false&quot;</span><span class="token punctuation">;</span></span>
